function escHtml(s){ return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function mdInline(s){ s=escHtml(s); s=s.replace(/`([^`]+)`/g,'<code>$1</code>'); s=s.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>'); s=s.replace(/\*([^*]+)\*/g,'<em>$1</em>'); s=s.replace(/\[([^\]]+)\]\(([^)]+)\)/g,'<a href="$2">$1</a>'); return s; }
function mdToHtml(src){
  var lines=String(src||'').replace(/\r/g,' ').split('\n'); var html=[], i=0, inList=false;
  function closeList(){ if(inList){ html.push('</ul>'); inList=false; } }
  for(i=0;i<lines.length;i++){ var L=lines[i]; var m;
    if((m=/^(#{1,6})\s+(.*)$/.exec(L))){ closeList(); var lv=m[1].length; html.push('<h'+lv+'>'+mdInline(m[2])+'</h'+lv+'>'); }
    else if(/^\s*[-*]\s+/.test(L)){ if(!inList){ html.push('<ul>'); inList=true; } html.push('<li>'+mdInline(L.replace(/^\s*[-*]\s+/,''))+'</li>'); }
    else if(L.trim()===''){ closeList(); }
    else { closeList(); html.push('<p>'+mdInline(L)+'</p>'); }
  }
  closeList(); return html.join('\n');
}

var EXPORTS={mdToHtml:mdToHtml};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.MarkdownToHtmlForgePure = EXPORTS; }
